//! I/O glue only: parse args, collect, execute the guest, judge the journal. Every decision
//! with logic in it lives in `le_sync` (lib.rs) where it is unit-tested. This file needs the
//! built guest ELF to run, so it is excluded from mutation testing (see `.cargo/mutants.toml`).

use le_sync::{collect_checked, judge, parse_args, usage_error_text, verdict_exit_code, Verdict};
use le_sync_wire::{check_chain_binding, GuestOutput};
use risc0_zkvm::{default_executor, ExecutorEnv};
use std::{env, process::ExitCode};

// Generated by build.rs: GUEST_ELF (bundled ProgramBinary) and GUEST_ID.
include!(concat!(env!("OUT_DIR"), "/methods.rs"));

fn main() -> ExitCode {
    env_logger::init();
    let opts = match parse_args(env::args().skip(1)) {
        Ok(o) => o,
        Err(e) => {
            eprint!("{}", usage_error_text(&e));
            return ExitCode::from(2);
        }
    };

    // 1. host does all I/O. `expected` is the chain binding built from the host's OWN
    //    configuration (never from what --other-chain / --cross-config alter).
    let collected = match collect_checked(&opts) {
        Ok(c) => c,
        Err(e) => {
            eprintln!("error: {e}");
            return ExitCode::FAILURE;
        }
    };

    // 2. guest does all verification (execute only: no proof is generated)
    let env = match ExecutorEnv::builder()
        .write(&collected.input)
        .and_then(|b| b.build())
    {
        Ok(e) => e,
        Err(e) => {
            eprintln!("error building executor env: {e}");
            return ExitCode::FAILURE;
        }
    };
    println!("executing guest (id {:?})...", GUEST_ID);
    let info = match default_executor().execute(env, GUEST_ELF) {
        Ok(i) => i,
        Err(e) => {
            eprintln!("guest execution failed: {e}");
            return ExitCode::FAILURE;
        }
    };

    // 3. trust only what the guest committed
    let out: GuestOutput = match info.journal.decode() {
        Ok(o) => o,
        Err(e) => {
            eprintln!("journal decode failed: {e}");
            return ExitCode::FAILURE;
        }
    };
    println!("cycles: {}", info.cycles());
    println!("journal: {out:?}");

    // The chain check is the first judgement made on the journal (see `judge`). Printing the
    // journal above is diagnostics only; nothing in it is trusted before that check.
    let verdict = judge(&opts, &out, collected.expected.as_ref());
    match &verdict {
        Verdict::Ok => {
            if let Some(exp) = collected
                .expected
                .as_ref()
                .filter(|_| opts.expects_chain_mismatch())
            {
                if let Err(e) = check_chain_binding(&out, exp) {
                    println!(
                        "chain mismatch detected, as expected for this run (code {}): {}",
                        e.code(),
                        e.message()
                    );
                }
            }
            println!("OK");
        }
        Verdict::ChainMismatch(e) => {
            eprintln!("CHAIN MISMATCH (code {}): {}", e.code(), e.message());
            if let Some(exp) = &collected.expected {
                eprintln!(
                    "  expected: chain_id {} genesis_validators_root 0x{}",
                    exp.chain_id,
                    hex::encode(exp.genesis_validators_root)
                );
            }
            eprintln!(
                "  journal:  chain_id {} genesis_validators_root 0x{}",
                out.chain_id,
                hex::encode(out.genesis_validators_root)
            );
        }
        Verdict::ChainMismatchNotDetected => eprintln!(
            "NOT OK: this run presented another chain, but the journal commits the host's own chain"
        ),
        Verdict::TrustedRootDiffers => {
            eprintln!("journal trusted_root differs from the requested one")
        }
        Verdict::NotOk => eprintln!("NOT OK"),
    }
    ExitCode::from(verdict_exit_code(&verdict))
}
